/*
  # Set cleaned_image_url for all catalog cars using imagin.studio transparent PNG URLs

  ## Summary
  Populates `cleaned_image_url` for all 318 cars that currently have Supabase Storage
  JPG images (which have white/grey backgrounds). Replaces them with imagin.studio URLs
  which return transparent PNG car renders — no white background, correct car colors.

  ## Changes
  - Sets `cleaned_image_url` for every car in car_catalog using the imagin.studio API
    format: `https://cdn.imagin.studio/getImage?customer=hrjavascript-mastery&make=X&modelFamily=Y&angle=23&width=600`
  - make and modelFamily values are mapped from the Swedish/local make/model names
  - Cars that already had imagin.studio image_url get their cleaned_image_url set too
    for consistency (useCarImages.ts prefers cleaned_image_url)

  ## Notes
  - imagin.studio returns transparent PNG renders — no CSS tricks needed
  - If imagin.studio doesn't have a model, it gracefully falls back to a generic render
  - The `angle=23` gives the standard 3/4 front-left perspective
*/

-- Helper: build imagin.studio URL
-- Format: make uses brand name, modelFamily uses model name with spaces replaced by hyphens

UPDATE car_catalog SET cleaned_image_url = CASE
  -- Alfa Romeo
  WHEN make = 'Alfa Romeo' AND model = 'Tonale' THEN 'https://cdn.imagin.studio/getImage?customer=hrjavascript-mastery&make=Alfa-Romeo&modelFamily=Tonale&angle=23&width=600'
  WHEN make = 'Alfa Romeo' THEN 'https://cdn.imagin.studio/getImage?customer=hrjavascript-mastery&make=Alfa-Romeo&modelFamily=' || replace(model, ' ', '-') || '&angle=23&width=600'
  -- Audi
  WHEN make = 'Audi' AND model = 'A1' THEN 'https://cdn.imagin.studio/getImage?customer=hrjavascript-mastery&make=Audi&modelFamily=A1&angle=23&width=600'
