  WHEN make = 'Volvo' AND model = 'V70' THEN 'https://cdn.imagin.studio/getImage?customer=hrjavascript-mastery&make=Volvo&modelFamily=V70&angle=23&width=600'
  WHEN make = 'Volvo' AND model = 'V90' THEN 'https://cdn.imagin.studio/getImage?customer=hrjavascript-mastery&make=Volvo&modelFamily=V90&angle=23&width=600'
  WHEN make = 'Volvo' AND model = 'V90 Cross Country' THEN 'https://cdn.imagin.studio/getImage?customer=hrjavascript-mastery&make=Volvo&modelFamily=V90&angle=23&width=600'
  WHEN make = 'Volvo' AND model = 'V40' THEN 'https://cdn.imagin.studio/getImage?customer=hrjavascript-mastery&make=Volvo&modelFamily=V40&angle=23&width=600'
  WHEN make = 'Volvo' AND model = 'V40 Cross Country' THEN 'https://cdn.imagin.studio/getImage?customer=hrjavascript-mastery&make=Volvo&modelFamily=V40&angle=23&width=600'
  WHEN make = 'Volvo' AND model = 'S60' THEN 'https://cdn.imagin.studio/getImage?customer=hrjavascript-mastery&make=Volvo&modelFamily=S60&angle=23&width=600'
  WHEN make = 'Volvo' AND model = 'S90' THEN 'https://cdn.imagin.studio/getImage?customer=hrjavascript-mastery&make=Volvo&modelFamily=S90&angle=23&width=600'
  WHEN make = 'Volvo' AND model = 'C40 Recharge' THEN 'https://cdn.imagin.studio/getImage?customer=hrjavascript-mastery&make=Volvo&modelFamily=C40-Recharge&angle=23&width=600'
